78	function sanitizeRuntimeOptions(
79	  options?: Partial<import('../types').EvaluateOptions>,
80	): Partial<import('../types').EvaluateOptions> | undefined {
81	  if (!options) {
82	    return undefined;
83	  }
84	
85	  // Create a deep copy to avoid mutating the original
86	  const sanitized = { ...options };
87	
88	  // Remove known non-serializable fields
89	  delete sanitized.abortSignal;
90	
91	  // Remove any function or symbol values
92	  for (const key in sanitized) {
93	    // biome-ignore lint/suspicious/noExplicitAny: FIXME this should use Object.keys or something to keep it type safe
94	    const value = (sanitized as any)[key];
95	    if (typeof value === 'function' || typeof value === 'symbol') {
96	      // biome-ignore lint/suspicious/noExplicitAny: FIXME this should use Object.keys or something to keep it type safe
97	      delete (sanitized as any)[key];
